// SetLogic replaces the registered business logic for this record only (tests); no
// arguments runs no triggers at all.
func (t *Customer) SetLogic(logic ...any) {
	for _, l := range logic {
		checkLogic(CustomerTableName, "Customer", l, customerTrigger)
	}
	if logic == nil {
		logic = []any{}
	}
	t.logic = logic
}

func (t *Customer) registeredLogic() []any {
	if t.logic != nil {
		return t.logic
	}
	return customerLogic
}

// runOnInsert runs the OnInsert triggers, then the field checks of the definition
func (t *Customer) runOnInsert() error {
	for _, l := range t.registeredLogic() {
		if trg, ok := l.(CustomerOnInsert); ok {
			if err := trg.OnInsert(t); err != nil {
				return err
			}
		}
	}
	return t.CheckFields()
}

